package httpapi
import("context";"crypto/rand";"encoding/hex";"encoding/json";"errors";"io";"log";"net/http";"path/filepath";"strings";"time";"github.com/ABHILASH9519/lunarreg-workbench/backend/go/internal/cv";"github.com/ABHILASH9519/lunarreg-workbench/backend/go/internal/jobs";"github.com/jackc/pgx/v5")
type Server struct{store *jobs.Store;worker *cv.Client;max int64;mux *http.ServeMux}
func New(st *jobs.Store,workerURL,uploadDir string,max int64)*Server{s:=&Server{store:st,worker:cv.New(workerURL),max:max,mux:http.NewServeMux()};s.routes();_ = uploadDir;return s}
func(s *Server)Handler()http.Handler{return s.mux}
func(s *Server)routes(){s.mux.HandleFunc("GET /healthz",func(w http.ResponseWriter,r *http.Request){jsonOut(w,200,map[string]string{"status":"ok","service":"lunarreg-go-api"})});s.mux.HandleFunc("GET /readyz",s.ready);s.mux.HandleFunc("GET /api/v1/jobs",s.list);s.mux.HandleFunc("POST /api/v1/jobs",s.create);s.mux.HandleFunc("GET /api/v1/jobs/{id}",s.get);s.mux.HandleFunc("DELETE /api/v1/jobs/{id}",s.delete)}
func(s *Server)ready(w http.ResponseWriter,r *http.Request){if _,e:=s.store.List(r.Context());e!=nil{jsonOut(w,503,map[string]string{"error":"database unavailable"});return};jsonOut(w,200,map[string]string{"status":"ready"})}
func(s *Server)list(w http.ResponseWriter,r *http.Request){v,e:=s.store.List(r.Context());if e!=nil{jsonOut(w,500,map[string]string{"error":"could not list jobs"});return};jsonOut(w,200,v)}
func(s *Server)get(w http.ResponseWriter,r *http.Request){v,e:=s.store.Get(r.Context(),r.PathValue("id"));if errors.Is(e,pgx.ErrNoRows){jsonOut(w,404,map[string]string{"error":"job not found"});return};if e!=nil{jsonOut(w,500,map[string]string{"error":"could not read job"});return};jsonOut(w,200,v)}
func(s *Server)delete(w http.ResponseWriter,r *http.Request){if e:=s.store.Delete(r.Context(),r.PathValue("id"));e!=nil{jsonOut(w,404,map[string]string{"error":"job not found"});return};w.WriteHeader(204)}
func(s *Server)create(w http.ResponseWriter,r *http.Request){r.Body=http.MaxBytesReader(w,r.Body,s.max*2+(1<<20));if e:=r.ParseMultipartForm(s.max);e!=nil{jsonOut(w,413,map[string]string{"error":"upload too large or malformed"});return};defer r.MultipartForm.RemoveAll();sf,sh,e:=r.FormFile("source");if e!=nil{jsonOut(w,400,map[string]string{"error":"source image is required"});return};defer sf.Close();rf,rh,e:=r.FormFile("reference");if e!=nil{jsonOut(w,400,map[string]string{"error":"reference image is required"});return};defer rf.Close();if !validName(sh.Filename)||!validName(rh.Filename){jsonOut(w,400,map[string]string{"error":"supported formats: PNG, JPG, JPEG, TIFF"});return};src,e:=io.ReadAll(io.LimitReader(sf,s.max+1));if e!=nil||int64(len(src))>s.max{jsonOut(w,413,map[string]string{"error":"source image exceeds upload limit"});return};ref,e:=io.ReadAll(io.LimitReader(rf,s.max+1));if e!=nil||int64(len(ref))>s.max{jsonOut(w,413,map[string]string{"error":"reference image exceeds upload limit"});return};cfg:=[]byte(r.FormValue("config"));if len(cfg)==0{cfg=[]byte("{}")};var check map[string]any;if json.Unmarshal(cfg,&check)!=nil{jsonOut(w,400,map[string]string{"error":"config must be valid JSON"});return};id:=newID();now:=time.Now().UTC();j:=jobs.Job{ID:id,Status:"processing",CreatedAt:now,UpdatedAt:now,SourceName:filepath.Base(sh.Filename),ReferenceName:filepath.Base(rh.Filename),Config:cfg};if e:=s.store.Create(r.Context(),j);e!=nil{jsonOut(w,500,map[string]string{"error":"could not create job"});return};ctx,cancel:=context.WithTimeout(r.Context(),3*time.Minute);defer cancel();result,e:=s.worker.Register(ctx,j.SourceName,j.ReferenceName,src,ref,cfg);if e!=nil{j.Status="failed";j.Error=e.Error();j.UpdatedAt=time.Now().UTC();_ = s.store.Update(context.Background(),j);jsonOut(w,502,j);return};var valid any;if json.Unmarshal(result,&valid)!=nil{j.Status="failed";j.Error="CV worker returned invalid JSON";j.UpdatedAt=time.Now().UTC();_ = s.store.Update(context.Background(),j);jsonOut(w,502,j);return};j.Status="completed";j.Result=result;j.UpdatedAt=time.Now().UTC();if e:=s.store.Update(r.Context(),j);e!=nil{log.Printf("persist result %s: %v",id,e);jsonOut(w,500,map[string]string{"error":"registration completed but persistence failed"});return};jsonOut(w,201,j)}
func validName(n string)bool{switch strings.ToLower(filepath.Ext(n)){case ".png",".jpg",".jpeg",".tif",".tiff":return true};return false}
func newID()string{b:=make([]byte,16);if _,e:=rand.Read(b);e!=nil{return time.Now().UTC().Format("20060102150405.000000000")};return hex.EncodeToString(b)}
func jsonOut(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.Header().Set("X-Content-Type-Options","nosniff");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
